#include <iostream>

using namespace std;

struct Point {
    long long x, y;
};

Point operator-(const Point& a, const Point& b) {
    return {a.x - b.x, a.y - b.y};
}

Point operator+(const Point& a, const Point& b) {
    return {a.x + b.x, a.y + b.y};
}

bool operator==(const Point& a, const Point& b) {
    return a.x == b.x && a.y == b.y;
}

long long dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y;
}

long long cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

long long distSq(const Point& a, const Point& b) {
    long long dx = a.x - b.x;
    long long dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Point p[8];
    for (int i = 1; i <= 7; ++i) {
        if (!(cin >> p[i].x >> p[i].y)) return 0;
    }

    // Condição 1: O ângulo ∠P2P1P3 é agudo (vértice em P1)
    Point v1 = p[2] - p[1];
    Point v2 = p[3] - p[1];
    if (dot(v1, v2) <= 0) {
        cout << "N\n";
        return 0;
    }

    // Condição 2: Os segmentos P1P2 e P1P3 têm o mesmo comprimento
    if (distSq(p[1], p[2]) != distSq(p[1], p[3])) {
        cout << "N\n";
        return 0;
    }

    // Condição 3: Os pontos P2, P3, P4 e P5 são colineares
    Point line_dir = p[3] - p[2];
    if (cross(line_dir, p[4] - p[2]) != 0 || cross(line_dir, p[5] - p[2]) != 0) {
        cout << "N\n";
        return 0;
    }

    // Condição 4: Os pontos médios dos segmentos P2P3 e P4P5 são coincidentes
    if (!(p[2] + p[3] == p[4] + p[5])) {
        cout << "N\n";
        return 0;
    }

    // Condição 5: O segmento P2P3 tem comprimento maior que o segmento P4P5
    if (distSq(p[2], p[3]) <= distSq(p[4], p[5])) {
        cout << "N\n";
        return 0;
    }

    // Condição 6: Os segmentos P4P6 e P5P7 são perpendiculares ao segmento P2P3
    if (dot(p[6] - p[4], line_dir) != 0 || dot(p[7] - p[5], line_dir) != 0) {
        cout << "N\n";
        return 0;
    }

    // Condição 7: Os segmentos P4P6 e P5P7 têm o mesmo comprimento
    if (distSq(p[4], p[6]) != distSq(p[5], p[7])) {
        cout << "N\n";
        return 0;
    }

    // Condição 8: Os pontos P1 e P6 devem estar separados pela reta que contém o segmento P2P3
    long long side1 = cross(line_dir, p[1] - p[2]);
    long long side6 = cross(line_dir, p[6] - p[2]);

    auto sgn = [](long long val) {
        if (val > 0) return 1;
        if (val < 0) return -1;
        return 0;
    };

    if (sgn(side1) * sgn(side6) >= 0) {
        cout << "N\n";
        return 0;
    }

    cout << "S\n";
    return 0;
}
